99	  const stepFrame = (delta: number) => {
100	    const video = videoRef.current;
101	    if (!video) return;
102	    video.pause();
103	    setIsPlaying(false);
104	    const newTime = Math.min(Math.max(video.currentTime + delta / fps, 0), video.duration);
105	    video.currentTime = newTime;
106	    setCurrentTime(newTime);
107	    overlayRef.current?.draw(Math.floor(newTime * fpsRef.current) + 1);
108	  };
109	
110	  const handleSeek = (time: number) => {
111	    const video = videoRef.current;
112	    if (!video) return;
113	    video.currentTime = time;
114	    setCurrentTime(time);
115	    overlayRef.current?.draw(Math.floor(time * fpsRef.current) + 1);
