141	  const [flashId, setFlashId] = useState<number | null>(null);
142	  const [hint, setHint] = useState(false);
143	  const [endOpen, setEndOpen] = useState(false);
144	  const [savingCount, setSavingCount] = useState(0);
145	  const [finishing, setFinishing] = useState(false);
146	  const [confirmDelete, setConfirmDelete] = useState(false);
147	  const [deletingFight, setDeletingFight] = useState(false);
148	  const [deleteError, setDeleteError] = useState<string | null>(null);
149	  // Timeline clip selected by click — Delete removes it. Separate from
150	  // `flashId` (a transient highlight after creation) and from `selected`
