152	  const [selectedEventId, setSelectedEventId] = useState<number | null>(null);
153	
154	  const frameRef = useRef(1);
155	  frameRef.current = currentFrame;
156	  const selRef = useRef<Corner | null>(null);
157	  selRef.current = selected;
158	  const endOpenRef = useRef(false);
159	  endOpenRef.current = endOpen;
160	  const confirmDeleteRef = useRef(false);
161	  confirmDeleteRef.current = confirmDelete;
162	  const selectedEventIdRef = useRef<number | null>(null);
163	  selectedEventIdRef.current = selectedEventId;
164	  const sessionIdsRef = useRef<number[]>([]);
165	
166	  const toastTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
167	  const hintTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
168	  const flashTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
169	
170	  const showToast = (text: string, color: string, icon: string) => {
171	    setToast({ text, color, icon });
172	    clearTimeout(toastTimer.current);
173	    toastTimer.current = setTimeout(() => setToast(null), 1100);
174	  };
175	
176	  const flash = (eventId: number) => {
