199	  const removeEvent = async (eventId: number) => {
200	    if (!fightId) return;
201	    setSavingCount(c => c + 1);
202	    try {
203	      await deleteEvent(fightId, eventId);
204	      setAllEvents(prev => prev.filter(e => e.id !== eventId));
