223	  // it once that data arrives, or the next O/P press opens a second span
224	  // instead of closing the first.
225	  useEffect(() => {
226	    for (const kind of ['corner_swap', 'excluded'] as const) {
227	      if (openSpanRef.current[kind] != null) continue;
228	      const open = spans.find(s => s.kind === kind && s.end_frame == null);
