from typing import List, Optional

from app.utils.db import run_db_query
from app.models.fight_event import FightEvent, FightEventCreate, FightEventUpdate
from app.models.round import Round


def get_events_by_fight(
    fight_id: int,
    fighter_id: Optional[int] = None,
    action: Optional[str] = None,
    success: Optional[bool] = None,
    kind: Optional[str] = None,
    source: Optional[str] = None,
) -> List[FightEvent]:
    def _query(session):
        if source == "label" and (kind is None or kind == "round"):
            _ensure_round_events_seeded(session, fight_id)

        q = session.query(FightEvent).filter(FightEvent.fight_id == fight_id)
        if fighter_id is not None:
            q = q.filter(FightEvent.fighter_id == fighter_id)
        if action:
            q = q.filter(FightEvent.action.ilike(f"{action}%"))
        if success is not None:
            q = q.filter(FightEvent.success.is_(success))
        if kind is not None:
            q = q.filter(FightEvent.kind == kind)
        if source is not None:
            q = q.filter(FightEvent.source == source)
        return q.order_by(FightEvent.frame).all()

    return run_db_query(_query)


def _ensure_round_events_seeded(session, fight_id: int) -> None:
    """Human-verified round bounds are seeded from AI segmentation the first
    time a fight's hand labels are fetched, so the labeller starts from a
    pre-filled boundary instead of marking every round from scratch. Must
    only ever run for a source='label' fetch — an ai_labeled fight's Player
    fetch (source='prediction') must never trigger this."""
    has_round_events = (
        session.query(FightEvent)
        .filter(
            FightEvent.fight_id == fight_id,
            FightEvent.source == "label",
            FightEvent.kind == "round",
        )
        .first()
    ) is not None
    if has_round_events:
        return

    rounds = (
        session.query(Round)
        .filter(Round.fight_id == fight_id)
        .order_by(Round.round_number)
        .all()
    )
    for r in rounds:
        session.add(FightEvent(
            fight_id=fight_id,
            source="label",
            kind="round",
            frame=r.start_frame,
            end_frame=r.end_frame,
            value=str(r.round_number),
        ))
    if rounds:
        session.commit()


def create_event(fight_id: int, payload: FightEventCreate) -> FightEvent:
    def _query(session):
        event = FightEvent(
            fight_id=fight_id,
            source="label",
            kind=payload.kind,
            frame=payload.frame,
            end_frame=payload.end_frame,
            description=payload.description,
            corner=payload.corner,
            action=payload.action,
            target=payload.target,
            success=payload.success,
            value=payload.value,
            labeler=payload.labeler,
        )
        session.add(event)
        session.commit()
        session.refresh(event)
        return event

    return run_db_query(_query)


def update_event(fight_id: int, event_id: int, payload: FightEventUpdate) -> Optional[FightEvent]:
    def _query(session):
        event = (
            session.query(FightEvent)
            .filter(
                FightEvent.id == event_id,
                FightEvent.fight_id == fight_id,
                FightEvent.source == "label",
                FightEvent.kind != "point",
            )
            .first()
        )
        if event is None:
            return None
        if payload.frame is not None:
            event.frame = payload.frame
        if payload.end_frame is not None:
            event.end_frame = payload.end_frame
        if payload.value is not None:
            event.value = payload.value
        session.commit()
        session.refresh(event)
        return event

    return run_db_query(_query)


def set_verified(fight_id: int, event_id: int, is_verified: Optional[bool]) -> Optional[FightEvent]:
    """Training Data QA's write path — independent of `update_event` (which
    is span-only, `kind != 'point'`) since a verdict is exactly the opposite
    scope: it only ever applies to a hand-labelled point event."""
    def _query(session):
        event = (
            session.query(FightEvent)
            .filter(
                FightEvent.id == event_id,
                FightEvent.fight_id == fight_id,
                FightEvent.source == "label",
                FightEvent.kind == "point",
            )
            .first()
        )
        if event is None:
            return None
        event.is_verified = is_verified
        session.commit()
        session.refresh(event)
        return event

    return run_db_query(_query)


def delete_event(fight_id: int, event_id: int) -> bool:
    def _query(session):
        # source='label' is the single most important guard in this
        # service: it makes it impossible for the Annotate delete endpoint
        # to ever remove a pipeline-predicted row.
        deleted = (
            session.query(FightEvent)
            .filter(
                FightEvent.id == event_id,
                FightEvent.fight_id == fight_id,
                FightEvent.source == "label",
            )
            .delete()
        )
        session.commit()
        return deleted > 0

    return run_db_query(_query)


def rounds_fully_annotated(fight_id: int, session=None) -> bool:
    """Every detected round has a (possibly labeller-adjusted) `round`-kind
    label event — the precondition finish-labeling gates on."""
    def _query(s):
        round_count = s.query(Round).filter(Round.fight_id == fight_id).count()
        event_count = (
            s.query(FightEvent)
            .filter(
                FightEvent.fight_id == fight_id,
                FightEvent.source == "label",
                FightEvent.kind == "round",
            )
            .count()
        )
        return round_count > 0 and event_count >= round_count

    if session is not None:
        return _query(session)
    return run_db_query(_query)

import { useMemo, useCallback, useEffect } from 'react';
import { useNavigate, useLocation, useParams, Link } from 'react-router-dom';
import { useTrainingDataEvents } from '../hooks/useTrainingDataEvents';
import type { QAEvent } from '../hooks/useTrainingDataEvents';
import { CLASS_BY_ACTION } from '../utils/trainingDataTaxonomy';
import { useWindowWidth } from '../hooks/useWindowWidth';
import ClassGrid from '../components/trainingData/ClassGrid';
import { classStats } from '../utils/trainingDataStats';
import EventTable from '../components/trainingData/EventTable';
import EventReview from '../components/trainingData/EventReview';

const classesPath = () => '/training-data';
const eventsPath = (action: string) => `/training-data/${action}`;
const detailPath = (action: string, id: number) => `/training-data/${action}/${id}`;

const sortEvents = (evs: QAEvent[]) =>
  [...evs].sort((a, b) => (a.fight.id === b.fight.id ? a.frame - b.frame : a.fight.id - b.fight.id));

export default function TrainingDataQA() {
  const width = useWindowWidth();
  const isMobile = width < 640;
  const narrow = width < 1080;

  const navigate = useNavigate();
  const location = useLocation();
  // `action` selects the training class, `eventId` (only present one level
  // deeper) selects the reviewed event within it — both real URL segments,
  // so a class list or a specific event's review is directly linkable/
  // bookmarkable/shareable, and browser back/forward walk the review history.
  const { action, eventId } = useParams<{ action?: string; eventId?: string }>();
  const id = eventId != null ? Number(eventId) : null;

  const { events, fights, loading, error, setVerdict } = useTrainingDataEvents();

  const eventsByAction = useMemo(() => {
    const m = new Map<string, QAEvent[]>();
    events.forEach((e) => {
      const key = e.action ?? '';
      const bucket = m.get(key);
      if (bucket) bucket.push(e); else m.set(key, [e]);
    });
    return m;
  }, [events]);

  const totals = classStats(events);

  const cls = action ? CLASS_BY_ACTION[action] : undefined;
  const evs = useMemo(() => (cls ? sortEvents(eventsByAction.get(cls.action) ?? []) : []), [cls, eventsByAction]);
  const ev = id != null ? evs.find((e) => e.id === id) ?? null : null;

  useEffect(() => { window.scrollTo({ top: 0 }); }, [action, id]);

  const nextPending = useCallback((fromId: number): number | null => {
    const idx = evs.findIndex((e) => e.id === fromId);
    if (idx === -1) return null;
    for (let k = 1; k <= evs.length; k++) {
      const c = evs[(idx + k) % evs.length];
      // `evs` is still last render's snapshot here (setVerdict's update hasn't
      // committed yet) — exclude fromId explicitly so a class with exactly
      // one pending event doesn't "advance" back onto itself.
      if (c.id !== fromId && c.is_verified == null) return c.id;
    }
    return null;
  }, [evs]);

  const onVerdict = useCallback((isVerified: boolean | null) => {
    if (!cls || id == null) return;
    const fightId = ev?.fight.id;
    if (fightId == null) return;
    setVerdict(id, fightId, isVerified);
    if (isVerified == null) return; // clearing a verdict never auto-advances
    const nx = nextPending(id);
    if (nx != null) setTimeout(() => navigate(detailPath(cls.action, nx), { replace: true }), 170);
    else setTimeout(() => navigate(eventsPath(cls.action), { replace: true, state: { justFinished: true } }), 240);
  }, [cls, id, ev, setVerdict, nextPending, navigate]);

  const onJumpRelative = useCallback((delta: 1 | -1) => {
    if (!cls || id == null || evs.length === 0) return;
    const idx = evs.findIndex((e) => e.id === id);
    const n = evs[(idx + delta + evs.length) % evs.length];
    navigate(detailPath(cls.action, n.id), { replace: true });
  }, [cls, id, evs, navigate]);

  const onJumpTo = useCallback((jumpId: number) => {
    if (!cls) return;
    navigate(detailPath(cls.action, jumpId), { replace: true });
  }, [cls, navigate]);

  const justFinished = (location.state as { justFinished?: boolean } | null)?.justFinished === true;

  let body: React.ReactNode;

  if (loading) {
    body = <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>Loading…</div>;
  } else if (error) {
    body = <div style={{ fontSize: 13, color: 'var(--red-500)' }}>{error}</div>;
  } else if (fights.length === 0) {
    body = (
      <div className="glass" style={{ padding: '20px 22px', fontSize: 13, color: 'var(--text-muted)' }}>
        No labelled fights yet. Upload a fight as "Self-annotate" and start labelling it in Annotate to build training data.
      </div>
    );
  } else if (!action) {
    body = (
      <>
        <div style={{ display: 'flex', alignItems: 'flex-end', gap: 24, flexWrap: 'wrap', marginBottom: 14 }}>
          <div style={{ minWidth: 0 }}>
            <h1 className="font-display" style={{ fontSize: isMobile ? 30 : 40, lineHeight: 0.94, margin: 0, color: 'var(--text-primary)' }}>
              TRAINING DATA
            </h1>
            <p style={{ margin: '6px 0 0', fontSize: 12.5, fontWeight: 600, color: 'var(--text-muted)' }}>
              Every hand-labelled event as the trainer sees it — replay the clip, keep it or drop it
            </p>
          </div>
          <div style={{ display: 'flex', gap: 26, flexWrap: 'wrap', marginLeft: 'auto' }}>
            <Stat label="events" value={totals.total} />
            <Stat label="confirmed" value={totals.confirmed} color="#0ca30c" />
            <Stat label="declined" value={totals.declined} color="#ef4444" />
          </div>
        </div>
        {totals.total > 0 && (
          <div style={{ display: 'flex', gap: 2, height: 6, borderRadius: 3, background: 'rgba(255,255,255,0.05)', overflow: 'hidden', marginBottom: 7 }}>
            <div style={{ width: `${(totals.confirmed / totals.total) * 100}%`, background: '#0ca30c' }} />
            <div style={{ width: `${(totals.declined / totals.total) * 100}%`, background: '#ef4444' }} />
          </div>
        )}
        <div style={{ margin: '0 0 22px', fontSize: 11, fontWeight: 600, color: 'var(--text-muted)' }}>
          {totals.reviewed} of {totals.total} reviewed · {totals.pending} pending · across {fights.length} labelled fight{fights.length === 1 ? '' : 's'}
        </div>
        <ClassGrid eventsByAction={eventsByAction} onOpen={(a) => navigate(eventsPath(a))} />
      </>
    );
  } else if (!cls) {
    body = (
      <div className="glass" style={{ padding: '20px 22px', fontSize: 13, color: 'var(--text-muted)' }}>
        "{action}" isn't a training class. <Link to={classesPath()}>Back to all classes</Link>.
      </div>
    );
  } else if (id == null) {
    body = justFinished ? (
      <div className="glass" style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 11, padding: '46px 30px', textAlign: 'center' }}>
        <span className="material-symbols-outlined" style={{ fontSize: 40, color: '#0ca30c' }}>task_alt</span>
        <div className="font-display" style={{ fontSize: 28, lineHeight: 1, color: 'var(--text-primary)' }}>{cls.name} reviewed</div>
        <p style={{ margin: 0, maxWidth: '46ch', fontSize: 12.5, fontWeight: 500, lineHeight: 1.6, color: 'var(--text-muted)' }}>
          Every {cls.name.toLowerCase()} event has a verdict. Pick another class or re-open the list.
        </p>
        <div style={{ display: 'flex', gap: 9, flexWrap: 'wrap', justifyContent: 'center' }}>
