1	import { useState, useEffect, useCallback } from 'react';
2	import { fetchFights, fetchEvents, verifyEvent, reclassifyEvent } from '../services/api';
3	import type { Fight } from '../types/Fight';
4	import type { Event } from '../types/Event';
5	import { TRAINING_ACTIONS } from '../utils/trainingDataTaxonomy';
6	import { isFrameSwapped } from '../utils/cornerSwap';
7	
8	export interface QAEvent extends Event {
9	  fight: Fight;
10	  /**
11	   * `corner`, flipped for display if this event's frame falls inside one of
12	   * its fight's confirmed `corner_swap` spans — same display-only correction
13	   * FighterOverlay/describeEvent apply elsewhere. `corner` itself stays the
14	   * raw label track-slot (see label-events-corner-is-box-not-person) and is
15	   * what still gets passed to ClipPlayer/FighterOverlay's `highlightCorner`,
16	   * since that matches against `fighter_frames.corner`, which lives in the
17	   * same unswapped slot space. `displayCorner` is for showing the reviewer
18	   * which corner actually threw the strike — text/colour only.
19	   */
20	  displayCorner: 0 | 1 | null;
21	}
22	
23	/**
24	 * Every reviewable hand-labelled point event across every labelled fight —
25	 * Training Data QA is cross-fight, unlike Player/Annotate which scope to one
26	 * `fightId`. Only `training_data`/`reference` fights that have actually
27	 * reached Annotate carry `source='label'` rows; an `ai_labeled` fight's
28	 * pipeline run never writes one.
29	 */
30	export const useTrainingDataEvents = () => {
31	  const [events, setEvents] = useState<QAEvent[]>([]);
32	  const [fights, setFights] = useState<Fight[]>([]);
33	  const [loading, setLoading] = useState(true);
34	  const [error, setError] = useState<string | null>(null);
35	
36	  const load = useCallback(() => {
37	    setLoading(true);
38	    setError(null);
39	    fetchFights()
40	      .then(async (allFights) => {
41	        const labelled = allFights.filter(
42	          (f) => f.purpose !== 'ai_labeled'
43	            && (f.state === 'labeling_in_progress' || f.state === 'labeling_complete'),
44	        );
45	        setFights(labelled);
46	        const perFight = await Promise.all(
47	          labelled.map((f) =>
48	            Promise.all([
49	              fetchEvents(f.id, { source: 'label', kind: 'point' }),
50	              fetchEvents(f.id, { source: 'label', kind: 'corner_swap' }),
51	            ]).then(([evs, swaps]) => {
52	              const spans = swaps.map((s) => ({ frame: s.frame, end_frame: s.end_frame }));
53	              return evs
54	                .filter((e) => TRAINING_ACTIONS.has(e.action ?? ''))
55	                .map((e) => ({
56	                  ...e,
57	                  fight: f,
58	                  displayCorner: (e.corner != null && isFrameSwapped(e.frame, spans)
59	                    ? 1 - e.corner
60	                    : e.corner) as 0 | 1 | null,
61	                }));
62	            }),
63	          ),
64	        );
65	        setEvents(perFight.flat());
66	      })
67	      .catch((err) => setError(err instanceof Error ? err.message : 'Unknown error'))
68	      .finally(() => setLoading(false));
69	  }, []);
70	
71	  useEffect(() => { load(); }, [load]);
72	
73	  const setVerdict = useCallback((eventId: number, fightId: number, isVerified: boolean | null) => {
74	    setEvents((prev) => prev.map((e) => (e.id === eventId ? { ...e, is_verified: isVerified } : e)));
75	    verifyEvent(fightId, eventId, isVerified).catch(() => {
76	      // Roll back to the server's actual state on failure.
77	      load();
78	    });
79	  }, [load]);
80	
81	  // Retypes a mislabelled strike (EventReview's "Type" dropdown). Persists
82	  // immediately — same optimistic-update-then-rollback-on-failure shape as
83	  // setVerdict — and, since it's a real fight_events write, is exactly what
84	  // Player/Annotate read back the next time either opens this fight: nothing
85	  // else needs to be told the type changed (see describeEvent.ts).
86	  const reclassify = useCallback((
87	    eventId: number, fightId: number, action: string, target: string | null, success: boolean | null,
88	  ): Promise<void> => {
89	    setEvents((prev) => prev.map((e) => (e.id === eventId ? { ...e, action, target, success } : e)));
90	    return reclassifyEvent(fightId, eventId, { action, target, success }).then(
91	      () => undefined,
92	      (err) => {
93	        // Roll back to the server's actual state on failure.
94	        load();
95	        throw err;
96	      },
97	    );
98	  }, [load]);
99	
100	  return { events, fights, loading, error, setVerdict, reclassify, refetch: load };
101	};
